android.extraProguardRules:
# expo-camera finds the ML Kit scanner by class name and ML Kit starts its parts by name from the manifest.
# Without these, R8 breaks the scanner in release builds and the QR camera never reports a code.
-keep class com.google.mlkit.** { *; }
-keep class com.google.android.gms.internal.mlkit_** { *; }
-keep class com.google.firebase.components.** { *; }
-keep class * implements com.google.firebase.components.ComponentRegistrar { *; }
